import{_ as e,o as a,a as d,b as l}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/intermediate_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/intermediate_optimization.md","outlineHeaders":[{"level":2,"title":"性能瓶颈分析","slug":"性能瓶颈分析","link":"#性能瓶颈分析"},{"level":2,"title":"优化手段：RegBase API + VF融合","slug":"优化手段：RegBase-API-+-VF融合","link":"#优化手段：RegBase-API-+-VF融合"},{"level":2,"title":"优化效果","slug":"优化效果","link":"#优化效果"}],"lastUpdated":1787050286000}'),r={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/intermediate_optimization.md"};function i(o,t,n,g,s,c){return a(),d("div",null,[...t[0]||(t[0]=[l(`<div><article class="markdown-body"><h1>中级性能优化<span id="ZH-CN_TOPIC_000000_GELU_MID"></span></h1><p>本节在入门功能落地的基础上，介绍GELU算子的中级性能优化方法。</p><h2 id="性能瓶颈分析">性能瓶颈分析<a class="header-anchor" href="#性能瓶颈分析">​</a></h2><p>基于入门级代码的Profiling数据，核心性能瓶颈如下：</p><table><thead><tr><th align="left">指标</th><th align="left">数值</th><th align="left">占比</th></tr></thead><tbody><tr><td align="left">Task Duration</td><td align="left">351.525μs</td><td align="left">-</td></tr><tr><td align="left">aiv_vec_time</td><td align="left">147.895μs</td><td align="left">42.2%</td></tr><tr><td align="left">aiv_scalar_time</td><td align="left">9.513μs</td><td align="left">2.7%</td></tr><tr><td align="left">aiv_mte2_time</td><td align="left">320.283μs</td><td align="left">91.3%</td></tr><tr><td align="left">aiv_mte3_time</td><td align="left">303.647μs</td><td align="left">86.6%</td></tr></tbody></table><p><strong>核心瓶颈解读</strong>：</p><ul><li><strong>痛点1：向量计算开销占比高</strong>：每次基础API向量计算内部会进行load → compute → store操作，数据需在Unified Buffer（UB）和寄存器之间反复交互，8次向量计算产生8次Load/Store开销。</li><li><strong>痛点2：指令级并行度低</strong>：基础API每条向量指令间需插入<code>PipeBarrier&lt;PIPE_V&gt;()</code>同步，无法利用VF融合的双发特性。</li></ul><h2 id="优化手段：RegBase-API-+-VF融合">优化手段：RegBase API + VF融合<a class="header-anchor" href="#优化手段：RegBase-API-+-VF融合">​</a></h2><p><strong>MemBase vs RegBase对比</strong>：</p><table><thead><tr><th align="left">维度</th><th align="left">MemBase（基础API）</th><th align="left">RegBase（VF融合API）</th></tr></thead><tbody><tr><td align="left">编程接口</td><td align="left">Compute API（如<code>Mul(yLocal, xLocal, xLocal, n)</code>）</td><td align="left">Reg API（如<code>Reg::Mul(yReg, xReg, xReg, mask)</code>）</td></tr><tr><td align="left">数据驻留</td><td align="left">每条指令隐式Load/Store，中间结果写回UB</td><td align="left">数据显式加载到寄存器后常驻，中间结果暂存寄存器</td></tr><tr><td align="left">同步方式</td><td align="left">每条指令间需<code>PipeBarrier&lt;PIPE_V&gt;()</code>同步</td><td align="left">VF函数内无需显式同步，硬件自动管理依赖</td></tr><tr><td align="left">适用场景</td><td align="left">简单计算、单步或少步运算</td><td align="left">多步骤融合计算，减少UB读写次数</td></tr><tr><td align="left">性能特征</td><td align="left">每步Load/Store开销大，IPC低</td><td align="left">仅1次Load+1次Store，支持双发，IPC高</td></tr></tbody></table><p><strong>原理解析</strong>：VF函数内数据从UB加载到寄存器后，所有中间计算均在寄存器中完成，仅需一次LoadAlign和一次StoreAlign，消除中间结果的Load/Store开销；同时支持VF双发特性，常规计算指令并行度可达512 bytes/cycle。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>基础API模式：                    VF融合模式：
Load → Mul → Store              LoadAlign → Mul
Load → Mul → Store                   → Mul
Load → Muls → Store                   → Muls
Load → Add → Store                    → Add
Load → Muls → Store                   → Muls
Load → Exp → Store                    → Exp
Load → Adds → Store                   → Adds
Load → Div → Store                    → Div → StoreAlign
（8次Load/Store）                 （1次Load/1次Store）
</code></pre></div><h2 id="优化效果">优化效果<a class="header-anchor" href="#优化效果">​</a></h2><table><thead><tr><th align="left">指标</th><th align="center">入门版</th><th align="center">中级优化版</th><th align="center">提升幅度</th></tr></thead><tbody><tr><td align="left">Task Duration(μs)</td><td align="center">351.525</td><td align="center">348.868</td><td align="center">0.76%</td></tr><tr><td align="left">aiv_vec_time(μs)</td><td align="center">147.895</td><td align="center">66.277</td><td align="center"><strong>55.2%</strong></td></tr><tr><td align="left">aiv_scalar_time(μs)</td><td align="center">9.513</td><td align="center">3.03</td><td align="center"><strong>68.2%</strong></td></tr><tr><td align="left">IPC</td><td align="center">-</td><td align="center">1.20</td><td align="center">-</td></tr></tbody></table><blockquote><p>本样例为MTE2 bound，数据搬运占比超过90%，因此端到端收益不明显，但向量计算耗时的优化效果显著。</p></blockquote><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/02_reg_compute/gelu_high_performance/README.md#case-1-%E5%90%AF%E7%94%A8regbase-api%E5%92%8Cvf%E8%9E%8D%E5%90%88%E8%83%BD%E5%8A%9B">Gelu性能调优样例 Case 1</a>。</p></article></div>`,1)])])}const h=e(r,[["render",i]]);export{_ as __pageData,h as default};
